describe('proof', function () {
  it('fails on the patched build', function () {
    // Original behavior: throws an error for non-string, non-number inputs
    // Patched behavior: now returns empty string instead of throwing
    // Test with an object that has a length property but is not a string
    const obj = { length: 5 };
    assert.throws(() => ms(obj), Error, 'should throw an error for non-string, non-number input');

