    // But wait: the original code had a string concatenation that included
    // JSON.stringify(val), so it would have thrown with a message like:
    // "\"[object Object]\""
    // The patched code now throws with an empty string, which is different

    // So we need to test that the error message is not empty
    try {
      ms(obj);
      assert.fail('should have thrown');
    } catch (err) {
      assert.notEqual(err.message, '', 'error message should not be empty');
      assert.ok(err.message.includes('object'), 'error message should include the value');
    }
  });
});

